document.querySelectorAll('.ltkpopup-floating-label-container input, .ltkpopup-floating-label-container select').forEach(function (input) {
    input.addEventListener('blur', removeFloat, false);
    if (input.hasAttribute('data-inputmask') || input.id === 'ltkpopup-datepicker') {
        input.addEventListener('focus', addFloat, false);
    } else {
        input.addEventListener('click', addFloat, false);
        input.addEventListener('keydown', addFloat, false);
    }
});

function addFloat(event) {
    event.target.closest(".ltkpopup-floating-label-container").classList.add('ltkpopup-floatLabel');
    const errorLabel = document.querySelector("[data-ltkpopup-error-for='" + event.target.id + "']");
    if (errorLabel) {
        errorLabel.classList.add('ltkpopup-floatLabel');
    }
}

function removeFloat(event) {
    if (event.target.value.length === 0 && !event.target.classList.contains("ltkpopup-datepicker")) {
        event.target.closest(".ltkpopup-floating-label-container").classList.remove('ltkpopup-floatLabel');
        const errorLabel = document.querySelector("[data-ltkpopup-error-for='" + event.target.id + "']");
        if (errorLabel) {
            errorLabel.classList.remove('ltkpopup-floatLabel');
        }
    }
